// Turn the vision service's ranked pages into a short list the agent can act on (no long text: keeps tokens low).
const r = $input.first().json;
if (r.error || !Array.isArray(r.results)) return [{ json: { response: 'VISUAL SEARCH UNAVAILABLE: the local vision service did not respond. '
  + 'Tell the user you could not check the drawings/page images right now. Do NOT say a sheet, figure or page does not exist.' } }];
if (!r.results.length) return [{ json: { response: 'No matching pages found.' } }];
const lines = r.results.map((p, i) => {
  const where = p.best_view === 'tile' ? ` (closest match: zoomed tile ${p.tile_ix})` : '';
  const why = (p.why || []).length ? ` — matched ${p.why.join('; ')}` : '';
  const snip = p.snippet ? `\n   text on page: ${p.snippet.slice(0, 140)}` : '';
  return `${i + 1}. ${p.file_name} — page ${p.page_no}${where} — ref ${p.ref}${why}${snip}`;
});
return [{ json: { response: 'Best-matching pages (found by how they look, by sheet/figure numbers and by keywords). '
  + 'To read one, call look_at_pages with its ref.\n' + lines.join('\n') } }];
